window.RP_SESSION={"id":"S-11abd48f5719","messages":[{"id":"RP-III-0054770","time":"2026-03-23T11:25:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"거친 숨소리가 고요를 깬다. 있는 힘껏 부딪혀 보는 저 검은 인영은, 이내 물러난다. 훈련장에서 과격하게 몸을 움직이는 저 인영은 잠이나 잘 자고 일어난 전사, 코왈로프스키였을 것이다. 음. 오늘은 늦잠을 잔 모양인데.","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054771","time":"2026-03-23T11:27:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"저번과 같이, 검을 휘둘러 곡선을 그려낸다. 숨이 차고, 심장은 터질 듯이 벅차오르는 이 기분.","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054772","time":"2026-03-23T11:28:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"저번과는 다르다. 저번과는 달랐다.","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054773","time":"2026-03-23T11:28:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"...나의 길은 틀리지 않았어.","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054774","time":"2026-03-23T11:29:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"가만 중얼이던 목소리엔, 피곤함이 묻어났다. 오늘은 좀 쉬어도 좋겠다만...","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054775","time":"2026-03-23T11:30:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"...겠는가! 난 앞으로도 더 강해져서, 나의 이름을 모두에게 알릴 것이다. 이런 것에 자만하지 않아!","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054776","time":"2026-03-23T11:30:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"언젠가, 위대한 펭귄으로 남을 때까지.","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054777","time":"2026-03-23T11:31:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"오늘도 검을 휘두른다. 그것이, 그가 선택한 길이자...","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054778","time":"2026-03-23T11:31:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"...","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054779","time":"2026-03-23T11:31:00+09:00","room":"RP III","name":"코왈로프스키","profile":"코왈로프스키","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-d6bf434d2e65"]},{"id":"RP-III-0054780","time":"2026-03-23T11:31:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]};
